$($p.Body)

        $(Get-CtaStrip -Heading "Ready to start your project?" -Text "Get a free, no-obligation estimate from Tropical Bay Builders." -EventLabel "blog_post_strip_phone")

        <p><a href="/blog.html">&larr; Back to all articles</a></p>
