        <a href="$PhoneTel" class="btn btn-primary btn-block" onclick="gtag('event','call_click',{'event_category':'engagement','event_label':'blog_sidebar_phone'})">Call $Phone</a>
        <a href="/#quote" class="btn btn-outline-dark btn-block" style="margin-top:10px;">Request Online</a>
      </aside>
    </div>
  </div>
</section>
"@
    $schema = Get-FaqSchema -Faqs @()
