          <div class=`"work-card-body`">
            <p style=`"color:#9aa5b1; font-size:0.85rem; margin-bottom:6px;`">$($_.DateDisplay)</p>
            <h3>$($_.Title)</h3>
            <p>$($_.Excerpt)</p>
          </div>
        </a>"
}) -join "`n"

$blogIndexBody = @"
